<?php
namespace App\Http\Controllers;
use App\Http\Requests\{FinalizeServisRequest,StartServisRequest,StoreDetailServisRequest,StoreServisSparepartRequest,UpdateInspectionRequest}; use App\Models\{BookingServis,Servis,DetailServis,ServisSparepart}; use App\Services\{ServisService,ServisSparepartService}; use Throwable;
class OperationsServisController extends Controller {
 public function index(){return view('operations.servis.index',['rows'=>Servis::with(['pelanggan','kendaraan','bookingServis','sparepartItems.sparepart'])->latest('id_servis')->paginate(20)]);}
 public function show(Servis $servis){$servis->load(['pelanggan','kendaraan','petugas','bookingServis.jenisServis','details.jenisServis','sparepartItems.sparepart','transaksi.pembayarans']);$promos=\App\Models\PromoMember::visible()->whereIn('berlaku_untuk',['semua','servis'])->get();return view('operations.servis.show-premium',compact('servis','promos'));}
 public function fromBooking(StartServisRequest $r,BookingServis $booking_servis,ServisService $svc){try{$svc->createFromBooking($booking_servis->id_booking_servis,(int)$r->user()->petugas->id_petugas,$r->validated('kilometer'),$r->validated('catatan'));return back()->with('success','Work Order berhasil dibuat.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}
 public function inspection(UpdateInspectionRequest $r,Servis $servis,ServisService $svc){try{$d=$r->validated();$svc->updateInspection($servis->id_servis,$d['hasil_pemeriksaan'],$d['catatan']??null);return back()->with('success','Hasil pemeriksaan tersimpan.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}
 public function detail(StoreDetailServisRequest $r,Servis $servis,ServisService $svc){try{$d=$r->validated();$svc->addDetail($servis->id_servis,$d['id_jenis_servis']??null,$d['deskripsi_pekerjaan'],$d['biaya'],$d['catatan']??null);return back()->with('success','Detail pekerjaan tersimpan.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}
 public function removeDetail(Servis $servis,DetailServis $detail_servis,ServisService $svc){try{$svc->removeDetail($servis->id_servis,$detail_servis->id_detail_servis);return back()->with('success','Detail pekerjaan dihapus.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}
 public function sparepart(StoreServisSparepartRequest $r,Servis $servis,ServisSparepartService $svc){try{$d=$r->validated();$svc->add($servis->id_servis,(int)$d['id_sparepart'],(int)$d['jumlah']);return back()->with('success','Draft spare part tersimpan.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}
 public function removeSparepart(Servis $servis,ServisSparepart $servis_sparepart,ServisSparepartService $svc){try{$svc->remove($servis->id_servis,$servis_sparepart->id_servis_sparepart);return back()->with('success','Draft spare part dihapus.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}
 public function finalize(FinalizeServisRequest $r,Servis $servis,ServisService $svc){try{$actor=$r->user()->petugas?->id_petugas ?? app(\App\Services\InventoryService::class)->actorPetugasId($r->user()->id_user);$tx=$svc->finalizeWithPromo($servis->id_servis,(int)$actor,$r->integer('promo_id')?:null);return back()->with('success','Servis difinalisasi dan transaksi '.$tx->kode_transaksi.' dibuat dengan status belum_bayar.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}
}
